// SPDX-License-Identifier: GPL-2.0 OR BSD-3-Clause
// RTL8852A static TX-power tables, verbatim from Linux
// `drivers/net/wireless/realtek/rtw89/rtw8852a_table.c` at torvalds/linux
// 067c5c24cef23d913b67eaaf71ae67e7169a6620 (SHA256 b5ff4992da105a766537f9553f08bda151c952ac45c3a4d2ceab7477e0b729db).
//
// Line ranges in that file: `rtw89_8852a_txpwr_byrate` 43286-43311
// (24 entries); `_txpwr_track_delta_swingidx_*` 43313-43380 (12 arrays,
// 30 entries each; the 5GHz arrays have 3 subband rows, the 2GHz arrays
// 1); `rtw89_8852a_txpwr_lmt_2g` 43382-45569 (2184 designated entries);
// `rtw89_8852a_txpwr_lmt_5g` 45572-47902 (2327);
// `rtw89_8852a_txpwr_lmt_ru_2g` 47905-48999 (1092);
// `rtw89_8852a_txpwr_lmt_ru_5g` 49002-50954 (1950);
// `rtw89_8852a_trk_cfg` 50987-51001; `rtw89_8852a_dflt_parms` 51002-51012.
//
// Units are Linux RF units (`txpwr_factor_rf` 2, `txpwr_factor_mac` 1 in
// `rtw8852a_chip_info`): the A plan stores them raw and shifts >> 1 at
// emit time, exactly as the B plan does. These bytes are a fixed power
// configuration, never a dBm authorization; final measured peaks and
// current host policy independently gate emission.
//
// Index conventions (core.h / phy.h at the same commit):
// band 0 = 2.4GHz, 1 = 5GHz; bw 0 = 20MHz, 1 = 40MHz, 2 = 80MHz
// (A `support_bandwidths` is 20/40/80 only, no 160MHz); ntx 0 = 1TX,
// 1 = 2TX; rs 0 = CCK, 1 = OFDM, 2 = MCS; bf 0 = non-BF, 1 = BF;
// regd is `enum rtw89_regulation_type` (WW 0, ETSI 1, FCC 2, MKK 3,
// IC 5, KCC 6, ACMA 7, MEXICO 9, CHILE 10, UKRAINE 11, CN 12,
// QATAR 13, UK 14); ch is `rtw89_channel_to_idx` (2.4GHz: ch - 1;
// 5GHz: 36..64 -> (ch-36)/2, 100..144 -> (ch-100)/2+15,
// 149..177 -> (ch-149)/2+38); ru 0 = RU26, 1 = RU52, 2 = RU106.
// The limit tables are sparse designated initializers in Linux:
// an unlisted cell reads 0. `lmt` / `lmt_ru` below return 0 for
// an unlisted cell, and `lmt_or_ww` mirrors phy.c
// `rtw89_phy_read_txpwr_limit{,_ru}`: a zero entry under the
// requested regd falls back to the WW entry.
//
// `rtw89_8852a_dflt_parms` (table.c:51002-51012) wires these tables
// as: `.byr_tbl = &rtw89_8852a_byr_table` (the 24 cfg entries below,
// loaded by phy.c `rtw89_phy_load_txpwr_byrate`), `.rule_2ghz =
// { .lmt = &rtw89_8852a_txpwr_lmt_2g, .lmt_ru =
// &rtw89_8852a_txpwr_lmt_ru_2g }`, `.rule_5ghz = { .lmt =
// &rtw89_8852a_txpwr_lmt_5g, .lmt_ru = &rtw89_8852a_txpwr_lmt_ru_5g }`;
// there is no per-RFE parms config (`rfe_parms_conf` is NULL).
// `rtw89_8852a_trk_cfg` (table.c:50987-51001) maps the twelve
// `enum rtw89_fw_txpwr_trk_type` values 4..=15 below to the delta
// arrays; the 6GHz types 0..=3 are NULL for 8852A (no 6GHz band).
//
// A has no `set_tx_shape` step (`rtw8852a_set_txpwr` in rtw8852a.c
// is byrate + offset + limit + limit_ru only, and
// `rtw8852a_chip_info.tssi_dbw_table` is NULL), so the A plan never
// consumes a TX_SHAPE_LMT element and never emits shape writes.

