/// phy.h `struct rtw89_txpwr_byrate_cfg`: (band, nss, rs, shf, len, data).
/// `data` packs `len` s8 values little-endian (phy.c
/// `rtw89_phy_load_txpwr_byrate`). Band 1 has no CCK row, as on B.
#[rustfmt::skip]
pub(super) const BYRATE: [(u8, u8, u8, u8, u8, u32); 24] = [
    (0, 0, 0, 0, 4, 0x50505050),
    (0, 0, 1, 0, 4, 0x50505050),
    (0, 0, 1, 4, 4, 0x484c5050),
    (0, 0, 2, 0, 4, 0x50505050),
    (0, 0, 2, 4, 4, 0x44484c50),
    (0, 0, 2, 8, 4, 0x34383c40),
    (0, 0, 3, 0, 4, 0x50505050),
    (0, 1, 2, 0, 4, 0x50505050),
    (0, 1, 2, 4, 4, 0x44484c50),
    (0, 1, 2, 8, 4, 0x34383c40),
    (0, 1, 3, 0, 4, 0x50505050),
    (0, 0, 4, 1, 4, 0x00000000),
    (0, 0, 4, 0, 1, 0x00000000),
    (1, 0, 1, 0, 4, 0x50505050),
    (1, 0, 1, 4, 4, 0x484c5050),
    (1, 0, 2, 0, 4, 0x50505050),
    (1, 0, 2, 4, 4, 0x44484c50),
    (1, 0, 2, 8, 4, 0x34383c40),
    (1, 0, 3, 0, 4, 0x50505050),
    (1, 1, 2, 0, 4, 0x50505050),
    (1, 1, 2, 4, 4, 0x44484c50),
    (1, 1, 2, 8, 4, 0x34383c40),
    (1, 1, 3, 0, 4, 0x50505050),
    (1, 0, 4, 0, 4, 0x00000000),
];

/// phy.c `rtw89_phy_load_txpwr_byrate` + `rtw89_phy_raw_byr_seek`: decode
/// [`BYRATE`] for one band into the 44-entry byrate layout the B plan
/// uses (CCK 4, OFDM 8, MCS nss0 12, HEDCM nss0 4, MCS nss1 12,
/// HEDCM nss1 4) and the 5-entry rate offset. Entries outside their
/// section are skipped (the generator proves the shipped table is
/// in bounds, so this is defense-in-depth, not a fallback).
pub(super) fn byrate(band: u8) -> ([i8; 44], [i8; 5]) {
    let mut rate = [0i8; 44];
    let mut offset = [0i8; 5];
    for &(b, nss, rs, shf, len, data) in BYRATE.iter() {
        if b != band {
            continue;
        }
        let (base, bound) = match (rs, nss) {
            (0, _) => (0, 4),
            (1, _) => (4, 8),
            (2, 0) => (12, 12),
            (2, 1) => (28, 12),
            (3, 0) => (24, 4),
            (3, 1) => (40, 4),
            (4, _) => (0, 5),
            _ => continue,
        };
        let (shf, len) = (usize::from(shf), usize::from(len));
        if shf + len > bound {
            continue;
        }
        for i in 0..len {
            let v = ((data >> (8 * i)) & 0xff) as u8 as i8;
            if rs == 4 {
                offset[shf + i] = v;
            } else {
                rate[base + shf + i] = v;
            }
        }
    }
    (rate, offset)
}

