/// `rtw89_8852a_trk_cfg`: the delta-swing row for a
/// `enum rtw89_fw_txpwr_trk_type` value and subband. 5GHz types
/// (4..=7) have 3 subband rows; 2GHz types (8..=15) have 1, so only
/// subband 0 is valid there. The 6GHz types (0..=3) are NULL for
/// 8852A and read as `None`, as does any out-of-range subband.
pub(super) fn delta_swing(trk_type: u8, subband: usize) -> Option<&'static [i8; 30]> {
    let rows: &[[i8; 30]] = match trk_type {
        4 => &DELTA_5GB_N,
        5 => &DELTA_5GB_P,
        6 => &DELTA_5GA_N,
        7 => &DELTA_5GA_P,
        8 => core::slice::from_ref(&DELTA_2GB_N),
        9 => core::slice::from_ref(&DELTA_2GB_P),
        10 => core::slice::from_ref(&DELTA_2GA_N),
        11 => core::slice::from_ref(&DELTA_2GA_P),
        12 => core::slice::from_ref(&DELTA_2G_CCK_B_N),
        13 => core::slice::from_ref(&DELTA_2G_CCK_B_P),
        14 => core::slice::from_ref(&DELTA_2G_CCK_A_N),
        15 => core::slice::from_ref(&DELTA_2G_CCK_A_P),
        _ => return None,
    };
    rows.get(subband)
}

