/// phy.c `rtw89_phy_read_txpwr_limit` at one regd: the raw RF-unit
/// limit for (band, bw, ntx, rs, bf, ch_idx); 0 for an unlisted cell.
pub(super) fn lmt(ghz5: bool, bw: u8, ntx: u8, rs: u8, bf: u8, regd: u8, ch_idx: u8) -> i8 {
    let table: &[(u8, u8, u8, u8, u8, u8, i8)] = if ghz5 { &LMT_5G } else { &LMT_2G };
    table
        .iter()
        .find(|&&(b, n, r, f, g, c, _)| {
            b == bw && n == ntx && r == rs && f == bf && g == regd && c == ch_idx
        })
        .map_or(0, |&(_, _, _, _, _, _, v)| v)
}

/// phy.c `rtw89_phy_read_txpwr_limit` with its WW fallback: a zero
/// entry under `regd` falls back to the WW entry (which may be 0).
pub(super) fn lmt_or_ww(ghz5: bool, bw: u8, ntx: u8, rs: u8, bf: u8, regd: u8, ch_idx: u8) -> i8 {
    if regd == WW {
        return lmt(ghz5, bw, ntx, rs, bf, regd, ch_idx);
    }
    let v = lmt(ghz5, bw, ntx, rs, bf, regd, ch_idx);
    if v != 0 {
        v
    } else {
        lmt(ghz5, bw, ntx, rs, bf, WW, ch_idx)
    }
}

/// phy.c `rtw89_phy_read_txpwr_limit_ru` at one regd: the raw RF-unit
/// RU limit for (band, ru, ntx, ch_idx); 0 for an unlisted cell.
pub(super) fn lmt_ru(ghz5: bool, ru: u8, ntx: u8, regd: u8, ch_idx: u8) -> i8 {
    let table: &[(u8, u8, u8, u8, i8)] = if ghz5 { &LMT_RU_5G } else { &LMT_RU_2G };
    table
        .iter()
        .find(|&&(r, n, g, c, _)| r == ru && n == ntx && g == regd && c == ch_idx)
        .map_or(0, |&(_, _, _, _, v)| v)
}

/// phy.c `rtw89_phy_read_txpwr_limit_ru` with its WW fallback.
pub(super) fn lmt_ru_or_ww(ghz5: bool, ru: u8, ntx: u8, regd: u8, ch_idx: u8) -> i8 {
    if regd == WW {
        return lmt_ru(ghz5, ru, ntx, regd, ch_idx);
    }
    let v = lmt_ru(ghz5, ru, ntx, regd, ch_idx);
    if v != 0 {
        v
    } else {
        lmt_ru(ghz5, ru, ntx, WW, ch_idx)
    }
}
